"""Config helpers."""


def clone(config):
    """Return an independent copy of `config`; mutating the copy never touches the original."""
    return dict(config)

original_test_src:
from cloner import clone

def test_equal():
    cfg = {'a': {'x': [1, 2]}, 'b': 1}
    assert clone(cfg) == cfg
    assert clone({}) == {}
def test_nested_list_independent():
    cfg = {'a': {'x': [1, 2]}, 'b': 1}
    c = clone(cfg)
    c['a']['x'].append(3)
    assert cfg['a']['x'] == [1, 2]
def test_nested_dict_independent():
    cfg = {'a': {'x': 1}}
    c = clone(cfg)
    c['a']['y'] = 2
    assert cfg['a'] == {'x': 1}
def test_list_of_dicts_independent():
    cfg = {'items': [{'n': 1}, {'n': 2}]}
    c = clone(cfg)
    c['items'][0]['n'] = 99
    c['items'].append({'n': 3})
    assert cfg == {'items': [{'n': 1}, {'n': 2}]}

